     1	import type {IncomingMessage} from '../../types/messages.js';
     2	
     3	const MAX_CONTENT_LENGTH = 10000;
     4	
     5	interface ValidationSuccess {
     6	  valid: true;
     7	  data: IncomingMessage;
     8	}
     9	
    10	interface ValidationFailure {
    11	  valid: false;
    12	  error: string;
    13	}
    14	
    15	export type ValidationResult = ValidationSuccess | ValidationFailure;
    16	
    17	export function validateMessage(payload: unknown): ValidationResult {
    18	  if (typeof payload !== 'object' || payload === null) {
    19	    return {valid: false, error: 'Message must be an object'};
    20	  }
    21	
    22	  const message = payload as Record<string, unknown>;
    23	
    24	  if (typeof message.type !== 'string') {
    25	    return {valid: false, error: 'Message must have a type field'};
    26	  }
    27	
    28	  const validator = validators[message.type];
    29	
    30	  return validator?.(message) ?? {valid: false, error: `Unknown message type: ${message.type}`};
    31	}
    32	
    33	const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
    34	  user_message: validateUserMessage,
    35	  ping: validatePingMessage,
    36	  list_sessions: validateListSessionsMessage,
    37	};
    38	
    39	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
    40	  if (typeof message.content !== 'string') {
    41	    return {valid: false, error: 'user_message must have content string'};
    42	  }
    43	
    44	  const trimmed = message.content.trim();
    45	
    46	  if (trimmed.length === 0) {
    47	    return {valid: false, error: 'Message content cannot be empty'};
    48	  }
    49	
    50	  if (message.content.length > MAX_CONTENT_LENGTH) {
    51	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
    52	  }
    53	
    54	  return {
    55	    valid: true,
    56	    data: {
    57	      type: 'user_message',
    58	      content: message.content,
    59	    },
    60	  };
    61	}
    62	
    63	function validatePingMessage(message: Record<string, unknown>): ValidationResult {
    64	  if (typeof message.timestamp !== 'number') {
    65	    return {valid: false, error: 'ping must have timestamp number'};
    66	  }
    67	
    68	  return {
    69	    valid: true,
    70	    data: {
    71	      type: 'ping',
    72	      timestamp: message.timestamp,
    73	    },
    74	  };
    75	}
    76	
    77	function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
    78	  const limit = message.limit;
    79	
    80	  if (limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0)) {
    81	    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    82	  }
    83	
    84	  if (message.before !== undefined) {
    85	    if (typeof message.before !== 'object' || message.before === null) {
    86	      return {valid: false, error: 'list_sessions before must be a cursor'};
    87	    }
    88	
    89	    const before = message.before as Record<string, unknown>;
    90	
    91	    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
    92	      return {valid: false, error: 'list_sessions before.sessionId must be 1 to 128 characters'};
    93	    }
    94	
    95	    if (!isValidTimestamp(before.updatedAt)) {
    96	      return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
    97	    }
    98	
    99	    return {
   100	      valid: true,
   101	      data: {
   102	        type: 'list_sessions',
   103	        ...(limit === undefined ? {} : {limit}),
   104	        before: {sessionId: before.sessionId, updatedAt: before.updatedAt},
   105	      },
   106	    };
   107	  }
   108	
   109	  return {
   110	    valid: true,
   111	    data: {
   112	      type: 'list_sessions',
   113	      ...(limit === undefined ? {} : {limit}),
   114	    },
   115	  };
   116	}
   117	
   118	function isValidTimestamp(value: unknown): value is string | number {
   119	  return (
   120	    (typeof value === 'string' && Number.isFinite(Date.parse(value))) ||
   121	    (typeof value === 'number' && Number.isFinite(value))
   122	  );
   123	}
