    33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
    34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
    35	  const lock = new PerSessionLock();
    36	  return function handleMessage(
    37	    ws: WebSocket,
    38	    session: ChatSession,
    39	    rawMessage: unknown,
    40	    signal?: AbortSignal
    41	  ): Promise<void> {
    42	    const validation = validateMessage(rawMessage);
    43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    44	    if (isUserMessageFrame(rawMessage)) {
    45	      return lock.run(session.sessionId, () =>
    46	        answerInTurn(ws, session, orchestrator, validation, sessionStore, signal)
    47	      );
    48	    }
    49	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    50	    return wsErrorHandler(ws, () => answerFrame(ws, session, validation, sessionStore));
    51	  };
    52	}
    53	
    54	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
    55	async function answerInTurn(
    56	  ws: WebSocket,
    57	  session: ChatSession,
    58	  orchestrator: ChatOrchestrator,
    59	  validation: ValidationResult,
    60	  sessionStore: SessionStore | undefined,
    61	  signal: AbortSignal | undefined
    62	): Promise<void> {
    63	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
    64	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    65	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    66	    return;
    67	  }
    68	  const startedAt = Date.now();
    69	  try {
    70	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, sessionStore, signal));
    71	  } finally {
    72	    endTurn(ws, session, signal, startedAt);
    73	  }
    74	}
    75	
    76	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
    77	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
    78	  if (signal?.aborted) {
    79	    log.info('message', 'turn abandoned: its socket closed', {
    80	      sessionId: session.sessionId,
    81	      elapsedMs: Date.now() - startedAt,
    82	    });
    83	    return;
    84	  }
    85	  sendStreamEnd(ws);
    86	}
    87	
    88	async function answerUserMessage(
    89	  ws: WebSocket,
    90	  session: ChatSession,
    91	  orchestrator: ChatOrchestrator,
    92	  validation: ValidationResult,
    93	  sessionStore: SessionStore | undefined,
    94	  signal: AbortSignal | undefined
    95	): Promise<void> {
    96	  const message = validation.valid ? validation.data : undefined;
    97	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
    98	  await answerFrame(ws, session, validation, sessionStore);
    99	}
