   101	async function answerFrame(
   102	  ws: WebSocket,
   103	  session: ChatSession,
   104	  validation: ValidationResult,
   105	  sessionStore?: SessionStore
   106	): Promise<void> {
   107	  if (!validation.valid) {
   108	    log.warn('message', 'validation failed', {error: validation.error});
   109	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
   110	    return;
   111	  }
   112	
   113	  const message = validation.data;
   114	  if (message.type === 'ping') return handlePing(ws, message.timestamp);
   115	  if (message.type === 'list_sessions')
   116	    return handleListSessions(ws, session, sessionStore, message.limit, message.before);
   117	}
   118	
   119	async function handleListSessions(
   120	  ws: WebSocket,
   121	  session: ChatSession,
   122	  sessionStore: SessionStore | undefined,
   123	  limit: number | undefined,
   124	  before: {updatedAt: string | number; sessionId: string} | undefined
   125	): Promise<void> {
   126	  try {
   127	    const summaries = (await sessionStore?.listFor?.(session.userId, {limit, before})) ?? [];
   128	    sendJson(ws, {
   129	      type: 'session_list',
   130	      sessions: summaries.map(summary => ({
   131	        ...summary,
   132	        createdAt: summary.createdAt.toISOString(),
   133	        updatedAt: summary.updatedAt.toISOString(),
   134	      })),
   135	    });
   136	  } catch (error) {
   137	    const message = error instanceof Error ? error.message : 'Unknown error';
   138	    log.error('ws', 'session list failed', {sessionId: session.sessionId, userId: session.userId, error: message});
   139	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
   140	  }
   141	}
   142	
   143	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
   144	function isUserMessageFrame(rawMessage: unknown): boolean {
   145	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
   146	}
   147	
   148	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
   149	  try {
   150	    await action();
   151	  } catch (error) {
   152	    const message = error instanceof Error ? error.message : 'Unknown error';
   153	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
   154	    log.error('message', 'handling error', {error: message, code});
   155	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
   156	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
   157	      return;
   158	    }
   159	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
   160	  }
   161	}
   162	
   163	async function handleUserMessage(
   164	  ws: WebSocket,
   165	  session: ChatSession,
   166	  orchestrator: ChatOrchestrator,
   167	  content: string,
   168	  signal: AbortSignal | undefined
   169	): Promise<void> {
   170	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
   171	
   172	  const userEntry = createUserEntry(content);
   173	  const userIndex = appendEntry(session, userEntry);
   174	  sendUpsert(ws, userIndex, userEntry);
   175	
   176	  const parser = new ThinkingTagParser();
   177	  const state: StreamState = {
   178	    thinkingIndex: null,
   179	    assistantIndex: null,
   180	    suppressOutput: false,
   181	    sentAssistantIndices: [],
   182	  };
   183	
   184	  let textChunkCount = 0;
   185	
   186	  try {
   187	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
   188	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
   189	      if (signal?.aborted) break;
   190	      textChunkCount = logChunk(chunk, textChunkCount);
   191	      processChunk(ws, session, state, parser, chunk);
   192	    }
   193	  } finally {
   194	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
   195	    flushHeldText(ws, session, state, parser);
   196	    closeCutOff(ws, session, state, 'thinkingIndex');
   197	    closeCutOff(ws, session, state, 'assistantIndex');
   198	  }
   199	
   200	  if (textChunkCount > 0) {
   201	    log.debug('stream', `received ${textChunkCount} text chunks`);
   202	  }
   203	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
   204	}
   205	
   206	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
   207	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
   208	  if (chunk.type === 'text') return textChunkCount + 1;
   209	
   210	  if (textChunkCount > 0) {
   211	    log.debug('stream', `received ${textChunkCount} text chunks`);
   212	  }
   213	
   214	  if (chunk.type === 'tool_result') {
   215	    log.debug('stream', 'tool_result chunk', {
   216	      messageCount: chunk.clientMessages.length,
   217	      types: chunk.clientMessages.map(m => m.type),
   218	    });
   219	    return 0;
   220	  }
   221	
   222	  log.debug('stream', 'chunk', {type: chunk.type});
   223	  return 0;
   224	}
