   226	function processChunk(
   227	  ws: WebSocket,
   228	  session: ChatSession,
   229	  state: StreamState,
   230	  parser: ThinkingTagParser,
   231	  chunk: MessageChunk
   232	): void {
   233	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
   234	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
   235	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
   236	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
   237	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
