    23	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
    24	
    25	const eventually = async (check: () => boolean): Promise<void> => {
    26	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
    27	};
    28	
    29	beforeEach(() => {
    30	  logLines.length = 0;
    31	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    32	    void logLines.push({level, category, message, fields});
    33	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
    34	});
    35	
    36	afterEach(async () => {
    37	  for (const client of clients.splice(0)) client.terminate();
    38	  for (const hal of servers.splice(0)) {
    39	    const {wss} = hal;
    40	    await eventually(() => wss.clients.size === 0);
    41	    await hal.stop();
    42	  }
    43	  setLogger();
    44	});
